    final class FlowDeal{private Database $db;public function __construct(Database $db){$this->db=$db;}public function execute(string $route,array $actor,array $body):array{return$this->db->transaction(function(Database $db)use($actor,$body):array{$o=$db->fetch('SELECT * FROM orders WHERE BINARY public_no=BINARY :n FOR UPDATE',['n'=>$body['order_id']]);$p='QCI'.bin2hex(random_bytes(8));$q=$db->insert("INSERT INTO quotes(public_id,order_id,worker_id,quote_type,amount_cents,current_version,status,created_at,updated_at) VALUES(:p,:o,:w,'worker',:a,1,'active',UTC_TIMESTAMP(),UTC_TIMESTAMP())",['p'=>$p,'o'=>$o['id'],'w'=>$actor['worker_id'],'a'=>$body['amount_cents']]);$db->insert("INSERT INTO quote_versions(quote_id,version_no,amount_cents,created_at) VALUES(:q,1,:a,UTC_TIMESTAMP())",['q'=>$q,'a'=>$body['amount_cents']]);$db->execute("UPDATE orders SET quote_status='quoting',version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=:id",['id'=>$o['id']]);return['message'=>'ok','data'=>['quote_id'=>$p]];});}}
    final class FlowSelect{private Database $db;public function __construct(Database $db){$this->db=$db;}public function execute(array $actor,array $body):array{return$this->db->transaction(function(Database $db)use($actor,$body):array{$q=$db->fetch("SELECT q.*,o.user_id,o.id oid FROM quotes q JOIN orders o ON o.id=q.order_id WHERE BINARY q.public_id=BINARY :q AND q.status='active' FOR UPDATE",['q'=>$body['quote_id']]);if(!$q||(int)$q['user_id']!==(int)$actor['user_id'])throw new \RuntimeException('quote unavailable');$r=$db->insert("INSERT INTO commission_rule_versions(order_id,locked_at,created_at) VALUES(:o,UTC_TIMESTAMP(),UTC_TIMESTAMP())",['o'=>$q['oid']]);$s=$db->insert("INSERT INTO quote_selections(order_id,quote_id,status,created_at) VALUES(:o,:q,'confirmed',UTC_TIMESTAMP())",['o'=>$q['oid'],'q'=>$q['id']]);$a=$db->insert("INSERT INTO assignments(public_id,order_id,worker_id,status,commission_rule_version_id,accepted_at,created_at,updated_at) VALUES(:p,:o,:w,'accepted',:r,UTC_TIMESTAMP(),UTC_TIMESTAMP(),UTC_TIMESTAMP())",['p'=>'ACI'.bin2hex(random_bytes(8)),'o'=>$q['oid'],'w'=>$q['worker_id'],'r'=>$r]);$db->insert("INSERT INTO assignment_history(assignment_id,order_id,worker_id,action,created_at) VALUES(:a,:o,:w,'accepted',UTC_TIMESTAMP())",['a'=>$a,'o'=>$q['oid'],'w'=>$q['worker_id']]);$db->execute("UPDATE quotes SET status=IF(id=:q,'selected','closed'),updated_at=UTC_TIMESTAMP() WHERE order_id=:o",['q'=>$q['id'],'o'=>$q['oid']]);$db->execute("UPDATE orders SET quote_status='selected',assignment_status='accepted',selected_quote_id=:q,assigned_worker_id=:w,current_assignment_id=:a,commission_rule_version_id=:r,final_amount_cents=:m,publish_status='hidden',fulfillment_status='not_started',version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=:o",['q'=>$q['id'],'w'=>$q['worker_id'],'a'=>$a,'r'=>$r,'m'=>$q['amount_cents'],'o'=>$q['oid']]);return['message'=>'ok','data'=>['selection_id'=>$s,'assignment_id'=>$a]];});}}
    final class FlowAppointment{private Database $db;public function __construct(Database $db){$this->db=$db;}public function save(array $actor,array $c):array{return$this->db->transaction(function(Database $db)use($actor,$c):array{$o=$db->fetch('SELECT * FROM orders WHERE BINARY public_no=BINARY :n FOR UPDATE',['n'=>$c['order_id']]);$id=$db->insert("INSERT INTO appointment_records(order_id,worker_id,appointment_at,note,status,context_type,after_sale_id,wait_customer_notice,created_at,updated_at) VALUES(:o,:w,:at,:note,'recorded','service',NULL,0,UTC_TIMESTAMP(),UTC_TIMESTAMP())",['o'=>$o['id'],'w'=>$actor['worker_id'],'at'=>str_replace('T',' ',$c['appointment_at']).':00','note'=>$c['note']]);$db->execute("UPDATE orders SET fulfillment_status='scheduled',version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=:o",['o'=>$o['id']]);return['message'=>'ok','data'=>['appointment_id'=>$id]];});}}
    final class FlowFulfillment{private Database $db;public function __construct(Database $db){$this->db=$db;}public function execute(string $route,array $actor,array $body):array{return$route==='fulfillment.complete'?$this->complete($actor,$body):$this->accept($actor,$body);}private function complete(array $actor,array $b):array{return$this->db->transaction(function(Database $db)use($actor,$b):array{$o=$db->fetch('SELECT * FROM orders WHERE BINARY public_no=BINARY :n FOR UPDATE',['n'=>$b['order_id']]);$c=$db->insert("INSERT INTO completion_submissions(order_id,worker_id,status,description,created_at,updated_at) VALUES(:o,:w,'submitted',:d,UTC_TIMESTAMP(),UTC_TIMESTAMP())",['o'=>$o['id'],'w'=>$actor['worker_id'],'d'=>$b['description']]);$db->insert("INSERT INTO order_deadlines(order_id,deadline_type,status,processed_at,created_at,updated_at) VALUES(:o,'auto_accept_completion','pending',NULL,UTC_TIMESTAMP(),UTC_TIMESTAMP())",['o'=>$o['id']]);$r=$db->insert("INSERT INTO commission_receivables(order_id,worker_id,assignment_id,is_provisional,finalized_at,created_at,updated_at) VALUES(:o,:w,:a,1,NULL,UTC_TIMESTAMP(),UTC_TIMESTAMP())",['o'=>$o['id'],'w'=>$actor['worker_id'],'a'=>$o['current_assignment_id']]);$db->execute("UPDATE orders SET fulfillment_status='submitted',completion_submitted_at=UTC_TIMESTAMP(),version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=:o",['o'=>$o['id']]);return['message'=>'ok','data'=>['completion_id'=>$c,'receivable_id'=>$r]];});}private function accept(array $actor,array $b):array{return$this->db->transaction(function(Database $db)use($actor,$b):array{$o=$db->fetch('SELECT * FROM orders WHERE BINARY public_no=BINARY :n FOR UPDATE',['n'=>$b['order_id']]);$db->execute("UPDATE completion_submissions SET status='accepted',updated_at=UTC_TIMESTAMP() WHERE order_id=:o AND status='submitted'",['o'=>$o['id']]);$db->execute("UPDATE commission_receivables SET is_provisional=0,finalized_at=UTC_TIMESTAMP(),updated_at=UTC_TIMESTAMP() WHERE order_id=:o",['o'=>$o['id']]);$db->execute("UPDATE order_deadlines SET status='completed',processed_at=UTC_TIMESTAMP(),updated_at=UTC_TIMESTAMP() WHERE order_id=:o AND deadline_type='auto_accept_completion' AND status='pending'",['o'=>$o['id']]);$db->insert("INSERT INTO order_deadlines(order_id,deadline_type,status,processed_at,created_at,updated_at) VALUES(:o,'auto_review','pending',NULL,UTC_TIMESTAMP(),UTC_TIMESTAMP())",['o'=>$o['id']]);$db->execute("UPDATE orders SET fulfillment_status='accepted',lifecycle_status='completed',accepted_at=UTC_TIMESTAMP(),version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=:o",['o'=>$o['id']]);$db->execute("UPDATE worker_profiles SET completed_orders=(SELECT COUNT(*) FROM orders WHERE assigned_worker_id=:w AND accepted_at IS NOT NULL),updated_at=UTC_TIMESTAMP() WHERE id=:w2",['w'=>$o['assigned_worker_id'],'w2'=>$o['assigned_worker_id']]);return['message'=>'ok','data'=>['accepted'=>true]];});}}
